 */
export class CartRepository {
  /**
   * 本地数据源实例
   */
  private dataSource: CartLocalDataSource;

  /**
   * 构造函数
   * @param {CartLocalDataSource} dataSource 可选的数据源实例
   */
  constructor(dataSource: CartLocalDataSource = new CartLocalDataSourceImpl()) {
