 */
@ComponentV2
export struct OrderGoodsItem {
  /**
   * 规格数据
   */
  @Param
  data: CartGoodsSpec = new CartGoodsSpec();
  /**
   * 商品 id
   */
  @Param
  goodsId: number = 0;
  /**
   * 商品名称
   */
  @Param
  goodsName: string = "";
  /**
   * 商品主图
   */
  @Param
  goodsMainPic: string = "";
  /**
   * 规格点击回调
   */
  @Param
  onSpecClick: (specId: number) => void = () => {
  };
  /**
   * 数量变更回调
   */
  @Param
  onQuantityChanged: (count: number) => void = () => {
  };
  /**
   * 是否启用数量调节器
   */
  @Param
  enableQuantityStepper: boolean = true;
  /**
   * 选择框插槽
   */
  @BuilderParam
  selectSlot?: CustomBuilder;
  /**
   * 操作插槽
   */
  @BuilderParam
  actionSlot?: CustomBuilder;

  /**
   * 构建订单商品条目
   * @returns {void} 无返回值
   */
  build(): void {
    RowStartCenter({
      widthValue: P100,
      paddingValue: {
        left: this.selectSlot ? 0 : $r("app.float.space_horizontal_large"),
        right: $r("app.float.space_horizontal_large"),
        bottom: $r("app.float.space_vertical_large")
      }
    }) {
      // 选择框插槽（购物车场景）
      if (this.selectSlot) {
        Column() {
          this.selectSlot();
        }
        .padding({ left: $r("app.float.space_horizontal_large") });

        SpaceHorizontalMedium();
      }

      // 商品图片
      NetWorkImage({
        model: this.data.images?.[0] ?? this.goodsMainPic,
        sizeValue: 90,
        showBackground: true,
        cornerRadius: $r("app.float.radius_small")
      });

      SpaceHorizontalMedium();

      // 商品信息
      Column() {
        ColumnStart() {
          // 商品规格 - 使用卡片样式
          Text(this.data.name)
            .fontSize($r("app.float.body_medium"))
            .fontColor($r("app.color.text_secondary"))
            .backgroundColor($r("app.color.bg_content"))
            .borderRadius(4)
            .padding({
              left: $r("app.float.space_padding_small"),
              right: $r("app.float.space_padding_small"),
              top: $r("app.float.space_padding_small_x"),
              bottom: $r("app.float.space_padding_small_x")
            })
            .onClick((): void => {
              this.onSpecClick(this.data.id);
            });

          SpaceVerticalMedium();

          // 价格和数量/操作区域
          RowSpaceBetweenCenter({ widthValue: P100 }) {
            // 价格
            IBestPrice({ value: this.data.price });

            // 数量控制器或自定义操作区域
            if (this.actionSlot) {
              this.actionSlot();
            } else if (this.enableQuantityStepper) {
              IBestStepper({
                value: this.data.count,
                min: 1,
                max: this.data.stock > 0 ? this.data.stock : 99,
                buttonRadius: 999,
                minusBtnBgColor: "#fff",
                minusBtnIconColor: $r("app.color.primary"),
                minusBtnBorderColor: $r("app.color.primary"),
                plusBtnBgColor: $r("app.color.primary"),
                plusBtnIconColor: "#fff",
                inputBgColor: "transparent",
                iconSize: 14,
                buttonSize: 22,
                onChange: (value: number): void => {
                  this.onQuantityChanged(value);
                }
              });
            } else {
              Text(`x${this.data.count}`)
                .fontSize($r("app.float.body_medium"))
                .fontColor($r("app.color.text_secondary"));
            }
          }
        }
      }
      .layoutWeight(1)
      .alignItems(HorizontalAlign.Start);
    }
  }
}
import { BaseViewModel } from "base";
import { getWindowSafeAreaState, WindowSafeAreaState } from "state";

/**
 * @file 通用导航容器：统一 NavDestination 与 ViewModel 生命周期转发
 * @author Joker.X
 */
@ComponentV2
export struct AppNavDestination {
  /**
   * 传入的视图模型实例（必传）
   */
  @Param
  @Require
  viewModel: BaseViewModel;
  /**
   * 业务内容渲染
   */
  @BuilderParam
  content: CustomBuilder;
  /**
   * 是否启用安全区（默认开启）
   */
  @Param
  safeAreaEnabled: boolean = true;
  /**
   * 是否隐藏标题栏（默认不隐藏）
   */
  @Param
  hideTitleBar: boolean = false;
  /**
   * 标题内容（可选）
   */
  @Param
  title: string | CustomBuilder | NavDestinationCommonTitle | NavDestinationCustomTitle | Resource = "";
  /**
   * 标题栏配置
   */
  @Param
  titleOptions: NavigationTitleOptions = {
    backgroundColor: $r("app.color.bg_grey")
  };
  /**
   * 导航栏菜单内容（可选）
   */
  @Param
  menus: Array<NavigationMenuItem> | CustomBuilder = [];
  /**
   * 导航栏菜单配置（可选）
   */
  @Param
  menuOptions: NavigationMenuOptions | undefined = undefined;
  /**
   * 页面背景色
   */
  @Param
  pageBackgroundColor: ResourceColor | ColorMetrics = $r("app.color.bg_grey");
  /**
   * 当前窗口安全区状态（可外部传入，默认内部获取）
   */
  @Param
  windowSafeAreaState: WindowSafeAreaState = getWindowSafeAreaState();
  /**
   * 自定义页面内边距（默认使用安全区）
   */
  @Param
  paddingValue: Padding | Length | LocalizedPadding | undefined = undefined;

  /**
   * 页面出现时的生命周期回调
   * @returns {void} 无返回值
   */
  aboutToAppear(): void {
    this.viewModel.aboutToAppear();
  }

  /**
   * 页面隐藏时的生命周期回调
   * @returns {void} 无返回值
   */
  aboutToDisappear(): void {
    this.viewModel.aboutToDisappear();
  }

  /**
   * 页面销毁时的生命周期回调
   * @returns {void} 无返回值
   */
  aboutToBeDeleted(): void {
    this.viewModel.aboutToBeDeleted();
  }

  /**
   * 组件构建完成（API 12+）
   * @returns {void} 无返回值
   */
  onDidBuild(): void {
    this.viewModel.onDidBuild();
  }

  /**
   * 组件即将回收
   * @returns {void} 无返回值
   */
  aboutToRecycle(): void {
    this.viewModel.aboutToRecycle();
  }

  /**
   * 主题即将应用
   * @param {Theme} theme - 主题对象
   * @returns {void} 无返回值
   */
  onWillApplyTheme(theme: Theme): void {
    this.viewModel.onWillApplyTheme(theme);
  }

  /**
   * 渲染通用 NavDestination
   * @returns {void} 无返回值
   */
  build() {
    NavDestination() {
      if (this.content) {
        this.content();
      }
    }
    .title(this.title, this.titleOptions)
    .hideTitleBar(this.hideTitleBar)
    .menus(this.menus, this.menuOptions)
    .onShown((reason: VisibilityChangeReason) => {
      this.viewModel.onShown(reason);
    })
    .onHidden((reason: VisibilityChangeReason) => {
      this.viewModel.onHidden(reason);
    })
    .backgroundColor(this.pageBackgroundColor)
    .padding(this.paddingValue ?? (this.safeAreaEnabled ? this.getSafeAreaPadding() : 0));
  }

  /**
   * 获取安全区内边距
   * @returns {Padding} 安全区内边距
   */
  private getSafeAreaPadding(): Padding {
    return {
      top: this.windowSafeAreaState.topInset,
      left: this.windowSafeAreaState.leftInset,
      bottom: this.windowSafeAreaState.bottomInset,
      right: this.windowSafeAreaState.rightInset
    };
  }
}
import {
  P100, RowSpaceBetweenCenter, RowStartCenter, SpaceHorizontalSmall
} from "designsystem";
import { IBestButton, IBestCheckbox, IBestPrice } from "ibestui";
import { getWindowSafeAreaState, WindowSafeAreaState } from "state";

/**
 * @file 购物车底部操作栏组件
 * @author Joker.X
 */
@ComponentV2
export struct CartBottomBar {
  /**
   * 是否全选
   */
  @Param
  isAllSelected: boolean = false;
  /**
   * 是否处于编辑模式
   */
  @Param
  isEditing: boolean = false;
  /**
   * 已选商品数量
   */
  @Param
  selectedCount: number = 0;
  /**
   * 已选商品总金额（单位：分）
   */
  @Param
  totalAmount: number = 0;
  /**
   * 全选状态变更回调
   */
  @Param
  onToggleSelectAll: () => void = () => {
  };
  /**
   * 删除按钮点击回调
   */
  @Param
  onDeleteClick: () => void = () => {
  };
  /**
   * 结算按钮点击回调
   */
  @Param
  onSettleClick: () => void = () => {
  };
  /**
   * 是否启用底部安全区
   */
  @Param
  safeAreaEnabled: boolean = true;
  /**
   * 当前窗口安全区状态（可外部传入，默认内部获取）
   */
  @Param
  windowSafeAreaState: WindowSafeAreaState = getWindowSafeAreaState();

  /**
   * 构建购物车底部操作栏
   * @returns {void} 无返回值
   */
  build(): void {
    Column() {
      RowSpaceBetweenCenter({
        widthValue: P100,
        paddingValue: {
          left: $r("app.float.space_horizontal_medium"),
          right: $r("app.float.space_horizontal_medium"),
          top: $r("app.float.space_vertical_medium"),
          bottom: this.safeAreaEnabled && this.windowSafeAreaState.bottomInset > 0
            ? 0
            : $r("app.float.space_vertical_medium")
        }
      }) {
        // 左侧：全选复选框
        RowStartCenter() {
          IBestCheckbox({
            value: this.isAllSelected,
            shape: "round",
            onChange: (): void => {
              this.onToggleSelectAll();
            }
          });

          SpaceHorizontalSmall();

          Text($r("app.string.select_all"))
            .fontSize($r("app.float.body_large"))
            .fontColor($r("app.color.text_primary"));
        }

        // 右侧：合计 + 结算按钮 或 删除按钮
        if (this.isEditing) {
          // 编辑模式：删除按钮
          IBestButton({
            text: this.selectedCount === 0
              ? $r("app.string.delete")
              : $r("app.string.delete_count", this.selectedCount),
            type: "danger",
            round: true,
            disabled: this.selectedCount === 0,
            btnWidth: 90,
            btnHeight: 34,
            onBtnClick: (): void => this.onDeleteClick()
          });
        } else {
          // 非编辑模式：合计 + 结算按钮
          RowStartCenter() {
            Text($r("app.string.total"))
              .fontSize($r("app.float.body_large"))
              .fontColor($r("app.color.text_primary"));

            SpaceHorizontalSmall();

            IBestPrice({ value: this.totalAmount });

            SpaceHorizontalSmall();

            IBestButton({
              text: this.selectedCount === 0
                ? $r("app.string.settle_account")
                : $r("app.string.settle_account_count", this.selectedCount),
              type: "primary",
              round: true,
              disabled: this.selectedCount === 0,
              btnWidth: 90,
              btnHeight: 34,
              onBtnClick: (): void => this.onSettleClick()
            });
          }
        }
      }

      if (this.safeAreaEnabled && this.windowSafeAreaState.bottomInset > 0) {
        Blank().height(this.windowSafeAreaState.bottomInset);
      }
    }
    .width(P100)
    .backgroundColor($r("app.color.bg_white"))
    .border({
      width: { top: 1 },
      color: $r("app.color.border")
    });
  }
}
import { ColumnStart, P100, SpaceVerticalMedium } from "designsystem";
import { Cart, CartGoodsSpec } from "model";
import { GoodsNavigator } from "navigation";
import { AppNavDestination, EmptyCart, OrderGoodsCard } from "ui";
import { IBestCheckbox } from "ibestui";
import CartViewModel from "../viewmodel/CartViewModel";
import { getWindowSafeAreaState, WindowSafeAreaState } from "state";
import { CartBottomBar } from "../component/CartBottomBar";

/**
 * @file 购物车页面视图
 * @author Joker.X
 */
@ComponentV2
export struct CartPage {
  /**
   * 购物车页面 ViewModel
   */
  @Local
  private vm: CartViewModel = new CartViewModel();
  /**
   * 当前窗口安全区状态
   */
  @Local
  private windowSafeAreaState: WindowSafeAreaState = getWindowSafeAreaState();
  /**
   * main 页面当前选中的页面索引
   */
  @Param
  currentPageIndex: number = 0;

  /**
   * 监听 main 页面当前选中的页面索引变化
   */
  @Monitor('currentPageIndex')
  onPageIndexChange() {
    if (this.currentPageIndex === 2) {
      this.vm.loadCartData();
    }
  }

  /**
   * 构建购物车页面
   * @returns {void} 无返回值
   */
  build() {
    AppNavDestination({
      title: $r("app.string.cart"),
      viewModel: this.vm,
      menus: this.vm.isEmpty ? [] : [
        {
          value: "",
          icon: this.vm.isEditing
            ? $r("app.media.ic_success")
            : $r("app.media.ic_edit"),
          action: (): void => {
            this.vm.toggleEditMode();
          }
        }
      ],
      paddingValue: {
        top: this.windowSafeAreaState.topInset,
        left: this.windowSafeAreaState.leftInset,
        right: this.windowSafeAreaState.rightInset
      },
    }) {
      ColumnStart({ fillMaxSize: true }) {
        this.CartContent();
        if (!this.vm.isEmpty) {
          CartBottomBar({
            safeAreaEnabled: false,
            isAllSelected: this.vm.isAllSelected,
            isEditing: this.vm.isEditing,
            selectedCount: this.vm.selectedCount,
            totalAmount: this.vm.totalAmount,
            onToggleSelectAll: (): void => {
              this.vm.toggleSelectAll();
            },
            onDeleteClick: (): void => {
              this.vm.deleteSelected();
            },
            onSettleClick: (): void => {
              this.vm.onSettleClick();
            },
            windowSafeAreaState: this.windowSafeAreaState
          });
        }
      }
    }
  }

  /**
   * 购物车页面内容视图
   * @returns {void} 无返回值
   */
  @Builder
  private CartContent() {
    if (this.vm.isEmpty) {
      EmptyCart();
    } else {
      List({ space: 12 }) {
        // 空的 ListItem 用于分隔购物车商品和底部栏
        ListItem() {
        }

        ForEach(this.vm.cartList, (cart: Cart) => {
          ListItem() {
            OrderGoodsCard({
              data: cart,
              onGoodsClick: (goodsId: number): void => {
                GoodsNavigator.toDetail(goodsId);
              },
              onQuantityChanged: (specId: number, count: number): void => {
                this.vm.updateSpecCount(cart.goodsId, specId, count);
              },
              enableQuantityStepper: true,
              itemSelectSlotBuilder: (spec: CartGoodsSpec): void => {
                this.CheckboxSlot(cart.goodsId, spec);
              }
            });
          }
        }, (cart: Cart): string => JSON.stringify(cart));
        ListItem() {
        }
      }
      .width(P100)
      .padding({
        left: $r("app.float.space_horizontal_medium"),
        right: $r("app.float.space_horizontal_medium"),
      })
      .layoutWeight(1)

      .scrollBar(BarState.Off);
    }
  }

  /**
   * 选择框插槽
   * @param {number} goodsId 商品ID
   * @param {CartGoodsSpec} spec 规格信息
   * @returns {void} 无返回值
   */
  @Builder
  private CheckboxSlot(goodsId: number, spec: CartGoodsSpec) {
    IBestCheckbox({
      value: this.vm.isSpecSelected(goodsId, spec.id),
      shape: "round",
      onChange: (): void => {
        this.vm.toggleSpecSelected(goodsId, spec.id);
      }
    });
  }
}
