from datetime import datetime, timezone
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent


def git(*args):
    return subprocess.check_output(['git', '-C', str(ROOT), *args])


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('output', help='Task-relative JSON output path')
    args = parser.parse_args()
    output = (ROOT / args.output).resolve()
    if not output.is_relative_to(ROOT) or output.suffix != '.json':
        raise ValueError('Output must be a JSON file inside this task')
    tracked = [p for p in git('ls-files', '-z').decode().split('\0') if p]
    untracked = [p for p in git('ls-files', '--others', '--exclude-standard', '-z').decode().split('\0')
                 if p and p.split('/')[0] in ('entry', 'core', 'feature')]
    files = []
    for name in sorted(set(tracked + untracked)):
        path = ROOT / name
        files.append({'path': name, 'sha256': hashlib.sha256(path.read_bytes()).hexdigest()
                      if path.is_file() else None})
    aggregate = ''.join(f"{x['path']}\0{x['sha256']}\n" for x in files).encode()
    data = {
        'captured_at': datetime.now(timezone.utc).isoformat(),
        'root': str(ROOT),
