import argparse
import hashlib
import json
import subprocess
from datetime import datetime, timezone
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent


def git(*args):
    return subprocess.check_output(['git', '-C', str(ROOT), *args])


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('output', help='Task-relative JSON output path')
    args = parser.parse_args()
    output = (ROOT / args.output).resolve()
    if not output.is_relative_to(ROOT) or output.suffix != '.json':
        raise ValueError('Output must be a JSON file inside this task')
    tracked = [p for p in git('ls-files', '-z').decode().split('\0') if p]
    untracked = [p for p in git('ls-files', '--others', '--exclude-standard', '-z').decode().split('\0')
                 if p and p.split('/')[0] in ('entry', 'core', 'feature')]
    files = []
    for name in sorted(set(tracked + untracked)):
        path = ROOT / name
        files.append({'path': name, 'sha256': hashlib.sha256(path.read_bytes()).hexdigest()
                      if path.is_file() else None})
    aggregate = ''.join(f"{x['path']}\0{x['sha256']}\n" for x in files).encode()
    data = {
        'captured_at': datetime.now(timezone.utc).isoformat(),
        'root': str(ROOT),
        'head': git('rev-parse', 'HEAD').decode().strip(),
        'base_commit': 'd6a6ba7480fbd0a30075462e46bb4344a430ba61',
        'status_tracked': git('status', '--short', '--untracked-files=no').decode(),
        'untracked_production': untracked,
        'aggregate_sha256': hashlib.sha256(aggregate).hexdigest(),
        'files': files,
    }
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text(json.dumps(data, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
    output.with_suffix('.patch').write_bytes(git('diff', '--binary', 'HEAD'))
    print(json.dumps({'manifest': str(output), 'files': len(files),
                      'aggregate_sha256': data['aggregate_sha256'],
                      'untracked_production': untracked}, ensure_ascii=False))


if __name__ == '__main__':
