import { BaseViewModel } from "base";
import { CartRepository, OrderCacheStoreRepository } from "data";
import { Cart, CartGoodsSpec, Goods, GoodsSpec, SelectedGoods } from "model";
import { OrderNavigator } from "navigation";
import { ToastUtils } from "util";

/**
 * @file 购物车页面 ViewModel
 * @author Joker.X
 */
@ObservedV2
export default class CartViewModel extends BaseViewModel {
  /**
   * 购物车仓库
   */
  private readonly cartRepository: CartRepository = new CartRepository();
  /**
   * 订单缓存本地存储仓库
   */
  private readonly orderCacheStoreRepository: OrderCacheStoreRepository = new OrderCacheStoreRepository();
  private unsubscribeChanges: (() => void) | null = null;
  private cartLoadTask: Promise<void> | null = null;
  private refreshPending: boolean = false;
  private disposed: boolean = false;

  aboutToAppear(): void {
    if (this.disposed) {
      return;
    }
    if (!this.unsubscribeChanges) {
      this.unsubscribeChanges = CartRepository.subscribeChanges((): void => {
        this.loadCartData();
      });
    }
    this.loadCartData();
  }

  onShown(reason: VisibilityChangeReason): void {
    this.loadCartData();
  }

  aboutToBeDeleted(): void {
    this.disposed = true;
    if (this.unsubscribeChanges) {
      this.unsubscribeChanges();
      this.unsubscribeChanges = null;
    }
  }
  /**
   * 购物车列表
   */
  @Trace
  cartList: Cart[] = [];
  /**
   * 选中的规格ID集合 (key: goodsId_specId)
   */
  @Trace
  selectedSpecIds: Set<string> = new Set();
  /**
   * 是否正在加载
   */
  @Trace
  isLoading: boolean = false;
  /**
   * 是否处于编辑模式
   */
  @Trace
  isEditing: boolean = false;

  /**
   * 获取选中的商品总数量
   * @returns {number} 选中商品数量
   */
  get selectedCount(): number {
    return this.selectedSpecIds.size;
  }

  /**
   * 获取选中商品的总价
   * @returns {number} 总价（单位：分）
   */
  get totalAmount(): number {
    let total = 0;
    for (const cart of this.cartList) {
      for (const spec of cart.spec) {
        const key = `${cart.goodsId}_${spec.id}`;
        if (this.selectedSpecIds.has(key)) {
          total += spec.price * spec.count;
        }
      }
    }
    return total;
  }

  /**
   * 是否全选
   * @returns {boolean} 是否全选
   */
  get isAllSelected(): boolean {
    if (this.cartList.length === 0) {
      return false;
    }
    for (const cart of this.cartList) {
      for (const spec of cart.spec) {
        const key = `${cart.goodsId}_${spec.id}`;
        if (!this.selectedSpecIds.has(key)) {
          return false;
        }
      }
    }
    return true;
  }

  /**
   * 购物车是否为空
   * @returns {boolean} 是否为空
   */
  get isEmpty(): boolean {
    return this.cartList.length === 0;
  }

  /**
   * 加载购物车数据
   * @returns {Promise<void>} Promise<void>
   */
  loadCartData(): Promise<void> {
    if (this.disposed) {
      return Promise.resolve();
    }
    this.refreshPending = true;
    if (!this.cartLoadTask) {
      this.cartLoadTask = this.refreshCartData();
    }
    return this.cartLoadTask;
  }

  private async refreshCartData(): Promise<void> {
    this.isLoading = true;
    try {
      do {
        this.refreshPending = false;
        try {
          const carts = await this.cartRepository.getAllCarts();
          if (this.disposed) {
            return;
          }
          this.cartList = carts;
          const remainingKeys = new Set<string>();
          for (const cart of carts) {
            for (const spec of cart.spec) {
              const key = `${cart.goodsId}_${spec.id}`;
              if (this.selectedSpecIds.has(key)) {
                remainingKeys.add(key);
              }
            }
          }
          this.selectedSpecIds = remainingKeys;
        } catch (error) {
          console.error(`[Cart] refresh failed: ${String(error)}`);
        }
